// The sample scores are bundled into the app as raw strings (Vite's "?raw"
// import), so they work offline and need no server. They are generated by
// scripts/generate-samples.mjs — edit that script and re-run it rather than
// hand-editing the XML.
import jazzTime from './jazz-time.musicxml?raw'
import jazzComping from './jazz-comping.musicxml?raw'
import jazzWaltz from './jazz-waltz.musicxml?raw'
import jazzFills from './jazz-triplet-fills.musicxml?raw'
import rockBeat from './rock-beat.musicxml?raw'
import grooveWithFills from './groove-with-fills.musicxml?raw'
import marching from './marching-8-on-a-hand.musicxml?raw'
import driftCheck from './drift-check-32-bars.musicxml?raw'

export interface SampleScore {
  id: string
  label: string
  /** Heading the sample is listed under in the score menu. */
  group: string
  xml: string
}

/** In menu order; the first one is loaded when the app opens. */
export const SAMPLES: SampleScore[] = [
  { id: 'jazz-time', group: 'Jazz', label: '1. Ride pattern & hi-hat (swing)', xml: jazzTime },
  { id: 'jazz-comping', group: 'Jazz', label: '2. Comping on snare & bass drum', xml: jazzComping },
  { id: 'jazz-waltz', group: 'Jazz', label: '3. Jazz waltz (3/4)', xml: jazzWaltz },
  { id: 'jazz-fills', group: 'Jazz', label: '4. Time & triplet fills', xml: jazzFills },
  { id: 'rock-beat', group: 'Rock & groove', label: 'Basic rock beat', xml: rockBeat },
  { id: 'groove-with-fills', group: 'Rock & groove', label: '8th-note groove with fills', xml: grooveWithFills },
  { id: 'marching-8-on-a-hand', group: 'Marching', label: 'Marching snare: 8 on a hand + accent/tap', xml: marching },
  { id: 'drift-check', group: 'Testing', label: 'Drift check: 32 bars at 160 BPM', xml: driftCheck },
]

/** Samples grouped by heading, keeping menu order. */
export const SAMPLE_GROUPS: { group: string; samples: SampleScore[] }[] = SAMPLES.reduce<{ group: string; samples: SampleScore[] }[]>(
  (groups, s) => {
    const g = groups.find((x) => x.group === s.group)
    if (g) g.samples.push(s)
    else groups.push({ group: s.group, samples: [s] })
    return groups
  },
  [],
)
